def transform(grid):
    g = np.array(grid)
    out = g.copy()
    H, W = g.shape
    emit(out.copy(), "Initial canvas: a 1-template with attached 2-markers, plus scaled 2-square targets.")
    comps = components(g != 0, diagonal=True)
    tmpl = None
    for c in comps:
        if any(g[y, x] == 1 for y, x in c):
            tmpl = c
            break
    if tmpl is None:
        return out
    y0, x0, _, _ = bbox(tmpl)
    ones = [(y - y0, x - x0) for y, x in tmpl if g[y, x] == 1]
    marks = sorted((y - y0, x - x0) for y, x in tmpl if g[y, x] == 2)
    tset = set(tmpl)
    targets = []
    for o in objects(g, bg=0):
        if o["colour"] != 2:
            continue
        if any(c in tset for c in o["cells"]):
            continue
        by0, bx0, by1, bx1 = o["box"]
        s = by1 - by0 + 1
        if bx1 - bx0 + 1 != s or o["size"] != s * s:
            continue
        targets.append((by0, bx0, s))
    used = set()
    if not marks:
        return out
    for t in targets:
        if t in used:
            continue
        my, mx, s = t
        oy = my - marks[0][0] * s
        ox = mx - marks[0][1] * s
        need = [(oy + ty * s, ox + tx * s, s) for ty, tx in marks]
        if not all(n in targets and n not in used for n in need):
            continue
        for n in need:
            used.add(n)
        for ty, tx in ones:
            for dy in range(s):
                for dx in range(s):
                    yy, xx = oy + ty * s + dy, ox + tx * s + dx
                    if 0 <= yy < H and 0 <= xx < W:
                        out[yy, xx] = 1
        emit(out.copy(), f"Stamped the template at scale {s} anchored on the 2-marker(s) at {need}.")
    emit(out.copy(), "Final: every set of target markers carries a scaled copy of the template.")
    return out
